namespace FoodExpiryApp; public class SettingsPage:ContentPage { public SettingsPage(){Title="Настройки";BackgroundColor=Color.FromArgb("#111116");var lang=new Picker{Title="Язык",ItemsSource=new[]{"Русский","English"},SelectedIndex=0};var theme=new Picker{Title="Тема",ItemsSource=new[]{"Тёмная","Светлая","Чёрная"},SelectedIndex=0};var accent=new Picker{Title="Акцентный цвет",ItemsSource=new[]{"Фиолетовый","Синий","Зелёный","Красный"},SelectedIndex=0};var date=new DatePicker{Date=DateTime.Today};var time=new TimePicker{Time=DateTime.Now.TimeOfDay};var support=new Button{Text="☕ Купить разработчику чашечку кофе",BackgroundColor=Color.FromArgb("#282431"),TextColor=Colors.White};support.Clicked+=async(_,_)=>await Navigation.PushAsync(new SupportPage());var info=new Button{Text="Инфо",BackgroundColor=Color.FromArgb("#282431"),TextColor=Colors.White};info.Clicked+=async(_,_)=>await Navigation.PushAsync(new InfoPage());Content=new ScrollView{Content=new VerticalStackLayout{Padding=22,Spacing=14,Children={new Label{Text="Настройки",FontSize=28,TextColor=Colors.White,FontAttributes=FontAttributes.Bold},lang,theme,accent,new Label{Text="Дата и время приложения",TextColor=Colors.White},date,time,new Label{Text="⚠ Синхронизация времени пока не подключена",TextColor=Color.FromArgb("#FF962E")},support,info,new Label{Text="FoodExpiryApp · версия 0.2.0",TextColor=Color.FromArgb("#B7B2C1")}}}};} }
